n = 0; loop (10000, megabuf(n)=gmegabuf(n)=0; n +=1; );

MINBPM = 70; MAXBPM = 200; num_res = 256; 
i = 0;
loop (num_res, megabuf(i*8)  = minbpm * pow(maxbpm/minbpm,i/(num_res-1)); i += 1;);

