presetParts.perFrame:
dt = min (1/fps,0.1); dec_m = 1 - 4*dt; dec_s = 1 - dt;
vol =  (bass+mid+treb)/3 ;
vol_ = vol_*dec_m + (1-dec_m)*vol; exc = vol-vol_;

beat = (vol>vol2) && (time-t0>.5);
if (beat, vol2=vol*5;t0=time,0);
vol2 *= dec_s;
idx += beat;

excite = atan (exc*2)/1.6;
index=0; ratio = log(maxbpm/minbpm); 
loop (num_res,
  n = index*8;
  omega      =   megabuf(n) * 6.2832/60;
  megabuf (n+1) *= 1-.5*dt; //damping
  ECS = int (8*omega*dt)+1; 
  loop (ECS,
    megabuf (n+1) += (excite - sqr(omega)*megabuf(n + 2)) * dt/ECS;
    megabuf (n+2) += megabuf(n+1) * dt/ECS);
  bc  = megabuf(n+1);  
  bs = megabuf(n+2)*omega; //2pi/60
  quad     = sqrt (bc*bc+bs*bs) ;
  megabuf (n+3) = megabuf(n+3) *dec_s +  quad* (1-dec_s);
  megabuf (n+4) = megabuf(n+3);
  megabuf (n+5) = bc;
  megabuf (n+6) = bs ;
  index += 1;
);

n = 0; maxind = 0; scale = .12;
loop (num_res,
  if (megabuf(n+3) > megabuf(maxind+3), maxind = n, 0);
  gmegabuf(n+5) = megabuf(n+5) * scale;
  gmegabuf(n+6) = megabuf(n+6) * scale;
n+=8;);

t1 += (3+mid_att)*dt*.1;
t2 += (3+bass_att)*dt*.1;
ob_g = .2* (sin (t2*.37)+1);
